import{_ as o,o as r,c as n,ah as s}from"./chunks/framework.DjU4PSOm.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-12T00:00:00.000Z"},"headers":[{"level":2,"title":"이번 시간 개요 (6주차-3, 10/12)","slug":"이번-시간-개요-6주차-3-10-12","link":"#이번-시간-개요-6주차-3-10-12","children":[]},{"level":2,"title":"1. 장 제목 — \\"쾌락 또는 고통의 가치, 어떻게 측정되는가\\"","slug":"_1-장-제목-—-쾌락-또는-고통의-가치-어떻게-측정되는가","link":"#_1-장-제목-—-쾌락-또는-고통의-가치-어떻게-측정되는가","children":[]},{"level":2,"title":"2. 여백 요약 \\"이 장의 용도\\"","slug":"_2-여백-요약-이-장의-용도","link":"#_2-여백-요약-이-장의-용도","children":[]},{"level":2,"title":"3. 본문 I — \\"쾌락과 고통의 회피는 입법자가 염두에 두는 목적이다 … 쾌락과 고통은 그가 다루는 도구이다\\"","slug":"_3-본문-i-—-쾌락과-고통의-회피는-입법자가-염두에-두는-목적이다-쾌락과-고통은-그가-다루는-도구이다","link":"#_3-본문-i-—-쾌락과-고통의-회피는-입법자가-염두에-두는-목적이다-쾌락과-고통은-그가-다루는-도구이다","children":[]},{"level":2,"title":"4. 본문 II — \\"한 사람 자신에게서, 쾌락·고통 그 자체의 가치는 네 사정에 따라 더 크거나 작다\\"","slug":"_4-본문-ii-—-한-사람-자신에게서-쾌락·고통-그-자체의-가치는-네-사정에-따라-더-크거나-작다","link":"#_4-본문-ii-—-한-사람-자신에게서-쾌락·고통-그-자체의-가치는-네-사정에-따라-더-크거나-작다","children":[]},{"level":2,"title":"5. 본문 III — \\"그러나 그 가치를 그것을 낳는 행위의 경향을 추정하려고 고려할 때는 두 사정이 더 있다\\"","slug":"_5-본문-iii-—-그러나-그-가치를-그것을-낳는-행위의-경향을-추정하려고-고려할-때는-두-사정이-더-있다","link":"#_5-본문-iii-—-그러나-그-가치를-그것을-낳는-행위의-경향을-추정하려고-고려할-때는-두-사정이-더-있다","children":[]},{"level":2,"title":"6. 각주 — 요소·차원, 기억용 시구","slug":"_6-각주-—-요소·차원-기억용-시구","link":"#_6-각주-—-요소·차원-기억용-시구","children":[]},{"level":2,"title":"7. 본문 30쪽 — 다산성(fecundity)과 순수성(purity)","slug":"_7-본문-30쪽-—-다산성-fecundity-과-순수성-purity","link":"#_7-본문-30쪽-—-다산성-fecundity-과-순수성-purity","children":[]},{"level":2,"title":"8. 주요 반론 (슬라이드 14~15쪽)","slug":"_8-주요-반론-슬라이드-14-15쪽","link":"#_8-주요-반론-슬라이드-14-15쪽","children":[]},{"level":2,"title":"9. 현대 사례 적용 (슬라이드 16쪽 — 일부만 진행)","slug":"_9-현대-사례-적용-슬라이드-16쪽-—-일부만-진행","link":"#_9-현대-사례-적용-슬라이드-16쪽-—-일부만-진행","children":[]},{"level":2,"title":"정리 한 문장","slug":"정리-한-문장","link":"#정리-한-문장","children":[]}],"relativePath":"philosophy/Ethics/14. 벤담 『서설』 4장 정독 — 쾌락 계산법과 반론(6주차-3).md","filePath":"philosophy/Ethics/14. 벤담 『서설』 4장 정독 — 쾌락 계산법과 반론(6주차-3).md"}'),g={name:"philosophy/Ethics/14. 벤담 『서설』 4장 정독 — 쾌락 계산법과 반론(6주차-3).md"};function l(i,t,e,u,a,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<blockquote><p>📎 <strong>슬라이드 위치</strong>: <code>26-2 윤리학 6강.pdf</code> 10~16쪽 (가치의 일곱 차원 ~ 정독: 4장 29–30쪽 ~ 절차 ~ 주요 반론 ~ 현대적 적용). 정독 대상 원문 사진은 <a href="./13. 슬라이드 속 책 사진·도해 번역(1~6주차).html">13. 슬라이드 속 책 사진·도해 번역(1~6주차)</a>의 6주차 11쪽 참고.</p></blockquote><h2 id="이번-시간-개요-6주차-3-10-12" tabindex="-1">이번 시간 개요 (6주차-3, 10/12) <a class="header-anchor" href="#이번-시간-개요-6주차-3-10-12" aria-label="Permalink to &quot;이번 시간 개요 (6주차-3, 10/12)&quot;">​</a></h2><ul><li>지난 온라인 강의(6-1, 6-2)는 <a href="./12. 벤담의 양적 공리주의(6주차 온라인).html">12. 벤담의 양적 공리주의(6주차 온라인)</a>에서 개요를 다뤘고, 이번 시간은 벤담 『도덕과 입법의 원리 서설』 <strong>4장(쾌락·고통의 가치, 측정 방법)</strong> 두 쪽을 <strong>학생이 소리 내어 읽은 뒤 문장 단위로 정독</strong>했다.</li><li>진행: 장 제목 → 여백 요약 → 본문 I·II·III → 각주(기억용 시구) → 30쪽의 다산성·순수성 → 주요 반론 → 현대 사례 적용. 시간이 끝나서 현대 적용은 <strong>사회 관계망 플랫폼과 복지 AI 사례의 앞부분</strong>까지만 나갔다.</li><li>수업 시작 때 휴일 잘 보냈는지 묻고, <strong>LMS에 올라온 녹화 강의를 보라</strong>고 권했다.</li><li>자막은 자동 인식·기계 번역이라 이름·용어가 많이 틀어져 있다(벤담 → 벤햄·벤자민·톰, propinquity → proficiency 등). 아래는 맥락에 맞게 바로잡았다. (원문: <a href="./Raw-Transcripts/2026-10-12_week6-3.html">6주차-3 자막 원문</a>)</li></ul><hr><h2 id="_1-장-제목-—-쾌락-또는-고통의-가치-어떻게-측정되는가" tabindex="-1">1. 장 제목 — &quot;쾌락 또는 고통의 가치, 어떻게 측정되는가&quot; <a class="header-anchor" href="#_1-장-제목-—-쾌락-또는-고통의-가치-어떻게-측정되는가" aria-label="Permalink to &quot;1. 장 제목 — &quot;쾌락 또는 고통의 가치, 어떻게 측정되는가&quot;&quot;">​</a></h2><ul><li><strong>lot</strong> = 복권이 아니라 <strong>양, 몫, 특정한 경우</strong>. 벤담은 &quot;특정한 쾌락·고통의 양을 어떻게 평가할까&quot;를 묻는다.</li><li>가장 철학적으로 도발적인 단어는 <strong>측정(measured)</strong>. 벤담은 쾌락과 고통이 <strong>완전히 비교 불가능하지는 않다</strong>고 가정한다.</li><li>킬로그램·미터 같은 완벽한 단위는 없어도 우리는 늘 비교한다 — &quot;어제보다 더 아팠다&quot;, &quot;이 즐거움이 더 오래 갔다&quot;, &quot;이 이익이 더 확실하다&quot;, &quot;이 정책이 더 많은 사람에게 영향을 준다&quot;. <strong>계산법(calculus)은 이런 일상의 비교 판단을 체계화</strong>한 것이다.</li><li>질문: 슬픔과 신체적 통증을 <strong>같은 척도</strong>에 올릴 수 있는가? 벤담은 <strong>실용적 비교는 가능</strong>하다고 믿을 것이고, 비판자는 <strong>질적으로 너무 다르다</strong>고 답할 것이다. → 이 논쟁이 나중에 <strong>벤담 vs 밀</strong>의 중심이 된다.</li></ul><h2 id="_2-여백-요약-이-장의-용도" tabindex="-1">2. 여백 요약 &quot;이 장의 용도&quot; <a class="header-anchor" href="#_2-여백-요약-이-장의-용도" aria-label="Permalink to &quot;2. 여백 요약 &quot;이 장의 용도&quot;&quot;">​</a></h2><ul><li>벤담은 쾌락에 대한 <strong>추상적 설명</strong>을 이론적 흥미로만 내놓는 게 아니다. 이 장은 <strong>입법자가 행위와 정책을 판단하는 방법</strong>을 주려는 <strong>실용적 기능</strong>을 한다.</li><li>그의 사상은 <strong>처음부터 정치적</strong>이다. 철학자이자 입법자로서, 개인이 어떻게 살아야 하는가만이 아니라 <strong>법이 어떻게 만들어져야 하는가</strong>를 묻는다.</li></ul><h2 id="_3-본문-i-—-쾌락과-고통의-회피는-입법자가-염두에-두는-목적이다-쾌락과-고통은-그가-다루는-도구이다" tabindex="-1">3. 본문 I — &quot;쾌락과 고통의 회피는 입법자가 염두에 두는 <em>목적</em>이다 … 쾌락과 고통은 그가 다루는 <em>도구</em>이다&quot; <a class="header-anchor" href="#_3-본문-i-—-쾌락과-고통의-회피는-입법자가-염두에-두는-목적이다-쾌락과-고통은-그가-다루는-도구이다" aria-label="Permalink to &quot;3. 본문 I — &quot;쾌락과 고통의 회피는 입법자가 염두에 두는 *목적*이다 … 쾌락과 고통은 그가 다루는 *도구*이다&quot;&quot;">​</a></h2><p>문장을 부분으로 나눠 읽었다.</p><ul><li><strong>&quot;쾌락과 고통의 회피&quot;</strong>: 앞선 장들에서 이미 <em>인간은 쾌락과 고통에 지배된다</em>고 논증했으므로 그 <strong>결론</strong>을 이어받은 표현. <strong>고통의 회피</strong>가 강조된다 — 긍정적 즐거움 만들기만이 아니라 <strong>고통 예방 그 자체가 근본적 도덕 목표</strong>.</li><li><strong>ends(목적)</strong>: 입법자의 궁극 목표는 <strong>쾌락의 생산과 고통의 예방</strong>. 이 문장은 입법자가 <em>전통 자체</em>를 보호하라, <em>통치자의 명예</em>를 지켜라, <em>한 종교 교리</em>를 강제하라고 말하지 않는다. <strong>공적 권위는 복지(well-being)에 미치는 효과로 평가</strong>된다. <ul><li>예: 엄한 처벌을 부과하면서도 사회의 범죄를 줄이지 못하는 형법은 <strong>고통만 낳고 더 큰 고통을 막지 못하므로</strong> 개정해야 한다.</li></ul></li><li><strong>토론 질문</strong>: 벤담의 목적 목록에서 <strong>빠진 것</strong>은? 정의, 권리, 평등, 자유, 존엄, 자율성, 덕 …. 벤담은 &quot;이런 가치도 쾌락에 기여하거나 고통을 막기 때문에 중요하다&quot;고 답할 수 있다. <strong>그 설명으로 충분한가</strong>는 비판자의 몫.</li><li><strong>&quot;It behooves him to understand their value&quot;</strong>: <em>behoove</em>는 &quot;~할 필요가 있다·해야 한다&quot;는 고어. <strong>him</strong>은 입법자가 늘 남성이라는 <strong>역사적 가정</strong>을 반영한다(현대 영어라면 their).</li><li><strong>논리 구조</strong>: ① 입법자는 쾌락 추구·고통 회피를 목표로 한다 ② 쾌락과 고통은 <strong>서로 다른 가치</strong>를 가진다 ③ 그러므로 입법자는 <strong>그것들을 비교하는 법</strong>을 알아야 한다. 정책 효과 평가를 거부하는 정부는 <strong>맹목적</strong>으로 행동한다.</li><li><strong>instruments(도구)</strong>: 벤담이 사람을 도구로 본다는 말이 아니다. <strong>보상·처벌·이익·부담·쾌락·고통</strong>이 <strong>법이 인간 행동에 영향을 미치는 수단</strong>이라는 뜻. 칸트의 &quot;사람을 단순한 수단으로 대하지 말라&quot;와는 층위가 다르다 — 칸트는 정책이 사람을 <strong>합리적 목적</strong>으로 존중하는지 묻고, 벤담은 정책·보상·처벌이 행동과 복지를 <strong>어떻게 바꾸는지</strong> 묻는다. <ul><li>벌금 = 고통의 기대를 만드는 수단, 세금 혜택 = 이익을 만드는 수단, 징역형 = 고통을 가해 일부 행위를 억제하는 수단.</li><li><strong>양날</strong>: 필요 이상으로 처벌하지 말라는 <strong>개혁</strong>의 언어가 될 수도, 사람이 <strong>행동 관리의 대상</strong>으로 전락하는 <strong>행정적 시선</strong>을 낳을 수도 있다. 현대판: 보상·순위·알림·페널티로 사용자 행동을 유도하는 <strong>알고리즘</strong>.</li></ul></li><li><strong>&quot;their force, which is again their value&quot;</strong>: <strong>force(힘)</strong> = 쾌락·고통이 행동과 복지에 미치는 <strong>영향력</strong>. 아무도 모르는 처벌은 억제력이 작고, 너무 작은 보상은 동기가 약하며, <strong>심각하지만 거의 안 일어나는 처벌</strong>은 <strong>중간 정도지만 매우 확실한 처벌</strong>보다 효과가 덜할 수 있다. 벤담은 쾌락·고통에 이름만 붙이는 게 아니라 <strong>그것이 무엇을 하는지</strong>를 본다.</li></ul><h2 id="_4-본문-ii-—-한-사람-자신에게서-쾌락·고통-그-자체의-가치는-네-사정에-따라-더-크거나-작다" tabindex="-1">4. 본문 II — &quot;한 사람 자신에게서, 쾌락·고통 <em>그 자체</em>의 가치는 네 사정에 따라 더 크거나 작다&quot; <a class="header-anchor" href="#_4-본문-ii-—-한-사람-자신에게서-쾌락·고통-그-자체의-가치는-네-사정에-따라-더-크거나-작다" aria-label="Permalink to &quot;4. 본문 II — &quot;한 사람 자신에게서, 쾌락·고통 *그 자체*의 가치는 네 사정에 따라 더 크거나 작다&quot;&quot;">​</a></h2><ul><li><strong>두 가지 고립</strong>: ① <strong>한 사람</strong>을 따로 본다 → 한 개인을 분석 출발점으로 삼는다 ② <strong>쾌락·고통 그 자체</strong>를 본다 → 넓은 결과를 따지기 전에 <strong>즉각적 감각</strong>만 일시적으로 본다. 벤담의 방법은 <strong>분석적</strong>이다.</li><li><strong>방법론적 개인주의</strong>: 공동체의 복지는 <strong>개별 구성원의 복지로부터 구성</strong>된다. 정부가 &quot;경제가 좋다&quot;고 하면 벤담은 <strong>&quot;어느 개인들이 좋아졌는가&quot;</strong> 를 묻게 한다 — 국민소득이 늘었다고 모두가 나아진 것은 아니다.</li><li><strong>&quot;greater or less&quot;</strong>: 쾌락·고통은 있다/없다가 아니라 <strong>정도</strong>(degree)를 가진다. 이 <strong>비교 구조</strong>가 도덕적 선택에 필요하다.</li></ul><p>네 가지 사정(차원)과 강의 예시:</p><table tabindex="0"><thead><tr><th>차원</th><th>설명</th><th>강의에서 든 예</th></tr></thead><tbody><tr><td><strong>① 강도(intensity)</strong></td><td>경험이 얼마나 센가</td><td>5분 기다리는 짜증 vs 치료 안 받은 병의 극심한 통증. 비용편익 분석이 둘 다 &quot;부정적 결과 1건&quot;으로 세면 부족하다. &quot;100시간의 가벼운 쾌락과 1시간의 극심한 고통을 맞바꾸겠는가?&quot; → <strong>강도와 지속의 비교</strong>가 필요</td></tr><tr><td><strong>② 지속성(duration)</strong></td><td>시간의 길이</td><td>일시적 통증 vs 영구 장애(초기 강도가 비슷해도 도덕적으로 다름). 새 교통 시스템: 공사 소음 6개월 vs 이후 수십 년의 통근 스트레스 감소. <strong>미래를 얼마나 멀리까지 계산할까?</strong> → <strong>기후 윤리</strong>에서 어려워짐(후손의 고통은 원인 제공자가 죽은 뒤에 일어남)</td></tr><tr><td><strong>③ 확실성(certainty)</strong></td><td>실제로 일어날 확률</td><td>정책 A: 부상 100건을 <em>확실히</em> 예방 vs 정책 B: 10% 확률로 2,000건 예방 → <strong>기댓값 추론</strong>. 그러나 <strong>확률은 도덕적으로 중립이 아니다</strong>: 어떤 데이터인가, 위험이 자발적으로 부과되는가, 누가 불확실성을 떠안는가. 예: 훈련 데이터에 인종·성별 편향이 있는 <strong>AI 의료 시스템</strong>의 회복 확률 추정은 구조적 불평등을 재생산할 수 있다</td></tr><tr><td><strong>④ 근접성(propinquity)</strong></td><td>시간적으로 얼마나 가까운가</td><td>학생이 공부 대신 즉각적 오락 선택(가까운 쾌락 vs 먼 이득). 정치인이 즉각적 경제 성장을 주지만 수십 년 뒤 환경 피해를 낳는 정책을 지지. 현대 영어로는 immediacy / delay</td></tr></tbody></table><ul><li><strong>&quot;each of them by itself&quot;</strong>: 아직 <strong>후속 효과의 연쇄는 고려하지 않았다</strong>는 뜻 — <strong>분석적 단순화</strong>. 실제 삶에서는 경험이 연결된다: 쾌락이 다른 쾌락을, 혹은 미래의 고통을 낳는다. 그래서 두 차원이 더 추가된다.</li></ul><h2 id="_5-본문-iii-—-그러나-그-가치를-그것을-낳는-행위의-경향을-추정하려고-고려할-때는-두-사정이-더-있다" tabindex="-1">5. 본문 III — &quot;그러나 그 가치를 그것을 낳는 <em>행위의 경향</em>을 추정하려고 고려할 때는 두 사정이 더 있다&quot; <a class="header-anchor" href="#_5-본문-iii-—-그러나-그-가치를-그것을-낳는-행위의-경향을-추정하려고-고려할-때는-두-사정이-더-있다" aria-label="Permalink to &quot;5. 본문 III — &quot;그러나 그 가치를 그것을 낳는 *행위의 경향*을 추정하려고 고려할 때는 두 사정이 더 있다&quot;&quot;">​</a></h2><ul><li>접속사 <strong>&quot;but&quot;</strong> 는 중요한 <strong>전환</strong>: <strong>감각의 가치 → 행위의 경향(tendency)</strong>. 두 평가 대상은 같지 않다.</li><li>예: <strong>중독성 약물</strong> — 그 감각만 보면 강렬·즉각적 쾌락으로 매우 가치 있어 보이지만, <strong>행위의 경향</strong>을 보면 의존, 질병, 재정 손실, 관계 파괴를 고려해야 한다.</li><li><strong>tendency</strong> = 행위가 낳는 효과의 <strong>예상 방향</strong>. 벤담은 고립된 사례에서 일어난 심리 상태만이 아니라 <strong>행위가 무엇을 낳기 쉬운가</strong>를 묻는다. 즉각 효과와 <strong>장기 효과</strong>를 함께 본다.</li></ul><h2 id="_6-각주-—-요소·차원-기억용-시구" tabindex="-1">6. 각주 — 요소·차원, 기억용 시구 <a class="header-anchor" href="#_6-각주-—-요소·차원-기억용-시구" aria-label="Permalink to &quot;6. 각주 — 요소·차원, 기억용 시구&quot;">​</a></h2><ul><li><strong>denominated</strong> = 명명되다. 벤담은 이 기준을 <strong>요소(elements)·차원(dimensions)</strong> 이라 부른다. 물체에 높이·너비·깊이가 있듯 쾌락에는 강도·지속·확실성·근접성이 있고, <strong>하나의 단순한 특징으로 환원되지 않는다</strong>(아주 강렬하지만 짧은 쾌락 vs 약하지만 오래 가는 쾌락).</li><li><strong>현대적 연결</strong>: 정책 시스템은 다차원 경험을 <strong>하나의 점수</strong>(건강 점수, 생산성 점수, 신용 점수, 위험 점수)로 압축한다. 벤담의 방법은 비교를 장려하지만 <strong>최종 숫자가 서로 매우 다른 차원을 가릴 수 있음</strong>을 상기시킨다.</li><li><strong>memorial(기억용) 시구</strong>: 독자가 차원을 외우도록 만든 짧은 시. <strong>&quot;입법에서 말의 전체 구조가 기대는 지점&quot;</strong> 이라는 표현이 아주 강하다 — 벤담은 계산법을 <strong>사소한 도구가 아니라 윤리·법적 판단의 토대</strong>로 본다. → 반문: 약속·존엄·역사적 부정의·불평등한 권력, <strong>침해가 총행복을 늘리더라도 침해되어선 안 되는 권리</strong>는? 각주에는 벤담의 <strong>지적 자신감과 이론의 야심</strong>이 함께 드러난다.</li></ul><p>시구를 한 줄씩:</p><ol><li><strong>Intense, long, certain, speedy, fruitful, pure</strong> — 형용사 하나가 차원 하나. intense=강도, long=지속, certain=확실성, speedy=근접성(빠름), fruitful=다산성, pure=순수성. (자막은 fruitful을 beautiful로 잘못 옮겼다.) <strong>범위(extent)</strong> 는 첫 줄에 없고, 개인의 경험에서 <strong>공공 정책</strong>으로 넘어갈 때 뒤에서 나온다.</li><li><strong>Such marks in pleasures and in pains endure</strong> — marks = <strong>특성</strong>. 이 차원들은 쾌락과 고통에 <strong>모두</strong> 적용된다. 예: 차별 정책의 고통은 강렬할 뿐 아니라 <strong>연쇄적</strong>이다(실업·빈곤·가족 스트레스·건강 악화·미래 배제).</li><li><strong>Such pleasures seek, if private be thy end</strong> — <em>thy</em> = your(고어). 목표가 <strong>사적 복지</strong>라면 이런 특성을 가진 쾌락을 구하라. 벤담은 <strong>도덕 이론을 신중함(prudence)의 추론과 연결</strong>한다. 자신을 위해 고르는 사람은 강하고, 길고, 가깝고, 미래의 쾌락을 낳고, 상대적으로 고통이 적은 쾌락을 택한다(규칙적 운동은 즉각적 쾌락이 가장 크진 않아도 지속·빈도·순수성에서 낫다).</li><li><strong>If it be public, wide let them extend</strong> — <strong>일곱째 차원(범위)</strong> 이 여기서 등장. <strong>public</strong>이 윤리적 관점을 바꾼다: 사적 신중함은 &quot;무엇이 <em>내</em> 삶을 낫게 하나&quot;, 공적 윤리는 <strong>&quot;영향받는 모든 사람의 삶을 낫게 하는 것은 무엇인가&quot;</strong>. 여기에 공리주의의 <strong>평등주의적·민주적 전제</strong>가 있다 — 공직자는 왕·귀족·기업·지배 집단<strong>만</strong>을 위해 봉사하면 안 된다. 다만 더 많은 사람에게 혜택을 주는 정책이 <strong>항상</strong> 낫다는 뜻은 아니다(해악의 강도와 분포도 중요). 벤담은 <strong>소수를 다수를 위해 희생하는 것을 절대적으로 금지하지 않는다</strong> → <strong>소수자 권리 반론</strong>의 출발점.</li><li><strong>Such pains avoid, whichever be thy view</strong> — 목적이 사적이든 공적이든 <strong>고통은 피해야 한다</strong>. 벤담은 고통을 그 자체로 미화하지 않는다. 고통은 <strong>더 큰 고통을 막거나 더 큰 쾌락을 낳을 때만</strong> 정당화된다. 예: 징역형은 고통스럽고, 공리주의자는 &quot;범죄자는 고통받아 마땅하니 고통은 선&quot;이라고 정당화할 수 없다. 벤담에게 <strong>처벌은 여전히 해악(evil)의 비용</strong>이며 더 심각한 해악을 막을 때에만 정당화된다.</li><li><strong>If pains must come, let them extend to few</strong> — 가장 중요하면서 <strong>불편한 줄</strong>. 선의의 해석: 고통을 완전히 피할 수 없다면 <strong>고통받는 사람 수를 최소화</strong>하라(임시 도로 폐쇄는 가능한 한 적은 주민에게 불편을 주도록). 그러나 <strong>분배 문제</strong>도 제기한다 — <strong>다수의 편안함을 위해 극심한 고통을 소수에게 집중</strong>시키는 것이 정당화될까? 예: 소수 노동자를 착취해 모두에게 값싼 음식을 주는 사회. 고통은 소수에게, 혜택은 다수에게 간다. 벤담은 그 소수의 고통의 <strong>강도·지속</strong>을 계산하게 하지만, <strong>충분히 큰 다수의 이익이 그것을 상쇄할 수 있다</strong>는 가능성은 여전히 열려 있다. <strong>칸트 윤리</strong>는 사람을 단지 수단으로 쓰면 안 된다고, <strong>정의론</strong>은 이익과 부담이 공정하게 분배되어야 한다고 반대할 것이다. → 각주는 공리주의의 <strong>도덕적 호소와 위험을 함께</strong> 담고 있다.</li></ol><h2 id="_7-본문-30쪽-—-다산성-fecundity-과-순수성-purity" tabindex="-1">7. 본문 30쪽 — 다산성(fecundity)과 순수성(purity) <a class="header-anchor" href="#_7-본문-30쪽-—-다산성-fecundity-과-순수성-purity" aria-label="Permalink to &quot;7. 본문 30쪽 — 다산성(fecundity)과 순수성(purity)&quot;">​</a></h2><ul><li><strong>⑤ 다산성</strong>: 같은 종류의 감각이 <strong>뒤따를 확률</strong>(쾌락이면 쾌락이, 고통이면 고통이). &quot;the chance it has&quot;는 <strong>확률</strong>적 표현. 예: 글 읽기를 배우면 즉각적 만족과 함께 문학·교육·고용·정치 정보·사회적 소통의 문이 열린다. 반대로 온라인 괴롭힘은 즉각적 공포에 더해 불면·사회적 위축·실직·우울·지속적 취약성으로 이어질 수 있다. 차별도 소득→주거→교육·건강으로 연쇄한다.</li><li><strong>⑥ 순수성</strong>: <strong>반대 종류의 감각이 뒤따르지 않을 확률</strong>. 쾌락은 고통이 뒤따를 가능성이 낮을 때 순수하고, 고통은 쾌락이 뒤따를 가능성이 낮을 때 순수하다. <ul><li>예: 소셜 미디어 알림은 즉각 쾌락을 주지만 반복되면 산만·불안·의존을 낳아 <strong>순수성이 낮다</strong>. 고통스러운 의료 시술은 <strong>회복과 건강 개선</strong>이 뒤따르므로 고통의 순수성이 낮은데, 이건 <strong>좋은 소식</strong>이다(반대 감각이 따라오므로).</li><li>벤담은 &quot;모든 고통을 즉시 피하라&quot;고 하지 않고 <strong>전체 인과 연쇄를 평가하라</strong>고 한다.</li></ul></li><li><strong>&quot;these two last … scarcely to be deemed properties of the pleasure or the pain itself&quot;</strong>: 다산성과 순수성은 <strong>엄밀히 말해</strong> 쾌락·고통 <strong>자체의 속성이 아니다</strong>. 앞의 네 차원(강도·지속·확실성·근접성)은 <strong>감각 자체</strong>의 특징이고, 다산성·순수성은 <strong>감각 이후에 일어나는 일</strong>이다. 쾌락은 자기 안에 미래 결과를 품고 있지 않다. 그것은 <strong>그 쾌락을 낳은 행위·사건의 속성</strong>이며, <strong>경험의 현상적 성격과 행위의 인과적 경향을 구별</strong>하는 것이다. <ul><li>&quot;in strictness&quot;(엄밀히)를 반복하는 건 <strong>개념적 정밀성</strong>을 위해서.</li><li>예: 단 음료의 첫 맛이 아무리 쾌적해도 건강에 미치는 미래 영향은 <strong>첫 맛의 느낌을 바꾸지 않는다.</strong> 하지만 <strong>그 음료를 마신 게 전반적으로 이로웠는지</strong>는 바꾼다.</li></ul></li><li><strong>&quot;act or other event&quot;</strong>: 평가 대상이 <strong>쾌락에서 행위·사건</strong>으로 옮겨 간다. &quot;other event&quot;는 분석을 <strong>의도적 인간 행위 너머</strong>로 확장한다 — 사고, 자연재해, 제도, <strong>기술 시스템</strong>도 쾌락·고통을 낳을 수 있다. 알고리즘은 일상적 의미의 의도를 경험하지 않지만 그 작동은 이익과 해악을 낳으므로 <strong>공리주의 분석을 기술 시스템에 적용할 수 있다.</strong></li><li><strong>tendency(경향)</strong> 는 고립된 결과가 아니라 <strong>패턴</strong>을 향한다. 예: 난폭운전을 하고도 우연히 아무도 다치게 하지 않은 운전자 — <strong>그 한 번의 실제 결과는 무해</strong>하지만 <strong>난폭운전의 경향은 위험</strong>하다. 결과주의자는 <strong>실제 결과만이 아니라 기대되는 결과</strong>를 평가해야 하며, 그래야 <em>운 좋았던 행동은 모두 옳다</em>는 결론을 피한다. (→ 칸트의 <strong>도덕적 운</strong> 논의와 비교: <a href="./11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인).html">11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인)</a>)</li></ul><h2 id="_8-주요-반론-슬라이드-14-15쪽" tabindex="-1">8. 주요 반론 (슬라이드 14~15쪽) <a class="header-anchor" href="#_8-주요-반론-슬라이드-14-15쪽" aria-label="Permalink to &quot;8. 주요 반론 (슬라이드 14~15쪽)&quot;">​</a></h2><p><strong>① 측정의 문제</strong></p><ul><li>쾌락·고통에는 <strong>자연적 수치 라벨</strong>이 없다: 견습 과정은 쾌락 몇 단위? 굴욕은 고통 몇 단위? 신체적 고통과 <strong>직접 비교</strong>되나?</li><li><strong>개인 간 비교</strong>: 나는 내 고통의 강도를 1인칭으로 알지만 <strong>남의 고통은 직접 경험하지 못한다.</strong> 증언·행동·의학 지식·사회적 이해·해석에 의존하는데 이 과정이 <strong>왜곡</strong>될 수 있다. 역사적으로 <strong>여성, 인종화된 집단, 장애인, 식민지 인구, 노동자, 수감자, 동물</strong>의 고통은 종종 <strong>과소평가</strong>돼 왔다. <strong>공리주의는 정보가 공정할 때만 공정</strong>하다(편향된 데이터 → 편향된 계산).</li><li>벤담의 계산법은 정확한 수치를 주기보다 <strong>주의를 안내</strong>할 수 있지만, <strong>대략의 비교를 과학적 확실성처럼 제시하는 순간 위험</strong>하다.</li></ul><p><strong>② 권리와 개인의 희생 — 장기 이식 사고실험</strong></p><ul><li>의사가 <strong>건강한 한 사람을 죽여 장기로 다섯 환자를 살릴 수 있다면?</strong> 단순 계산은 5명 &gt; 1명이라고 하겠지만 대부분은 허용 불가로 본다. 건강한 사람은 <strong>권리</strong>가 있고, <strong>동의하지 않았고</strong>, 의사는 그를 <strong>단지 수단으로</strong> 쓰며, 그런 행위는 <strong>의학에 대한 신뢰를 파괴</strong>한다.</li><li>공리주의자는 <strong>두려움·불신·제도적 효과</strong>까지 계산에 넣어 답할 수 있지만 <strong>더 깊은 질문</strong>이 남는다: 그 사람은 <em>죽이면 대체로 나쁜 결과가 나서</em> 보호받는가, 아니면 <strong>거래되어선 안 되는 권리를 가졌기 때문</strong>에 보호받는가? 칸트적 입장은 후자의 답을 준다.</li></ul><p><strong>③ 정의와 분배</strong></p><ul><li>공리주의는 보통 복지의 <strong>합계(균형)</strong> 를 평가하지만 <strong>같은 총량</strong>도 아주 다르게 분배될 수 있다. 사회 A(모두 중간 수준) vs 사회 B(소수 엘리트는 막대한 쾌락, 다수는 결핍), 총 쾌락이 같다면 도덕적으로 동등한가? <strong>많은 정의론은 아니라고 한다.</strong> 분배는 총량과 <strong>별개로</strong> 중요하다.</li><li>핵심 반론: 공리주의는 <strong>일부 사람들에게 부과된 손실을 전혀 다른 사람들이 얻은 이득으로 보상 가능한 것</strong>으로 다룰 수 있다.</li></ul><p><strong>④ 소수자 억압</strong></p><ul><li>다수가 소수를 모욕하며 쾌감을 얻는다면? 쾌락은 <strong>넓게 퍼지고</strong>, 고통은 <strong>집중</strong>된다. 다수의 만족이 소수의 고통을 이길 수 있는가? 벤담의 계산은 억압의 <strong>강도·지속·불순성</strong>을 따져 억압을 강하게 부정적으로 만들 수 있지만 <strong>절대적 장벽은 없다</strong> — 숫자가 다르게 배열되면 이론상 <strong>정당화</strong>할 수 있다. 그래서 <strong>권리는 흔히 &#39;집계(aggregation)에 대한 보호&#39;</strong> 로 이해된다.</li></ul><p><strong>⑤ 쾌락의 질</strong></p><ul><li>어려운 철학 개념을 이해하는 기쁨이 <strong>단 음식 먹는 기쁨의 단순히 더 큰 양</strong>인가? 우정은 <strong>쾌적한 감각을 만들기 때문에만</strong> 중요한가? 지식은 <strong>고통스러울 때도</strong> 가치 있는가? <strong>밀</strong>은 <strong>고급·저급 쾌락</strong>을 구분해 응답했지만 <strong>누가 쾌락의 서열을 매길 권한이 있는가</strong>라는 새 질문이 생긴다.</li></ul><p><strong>⑥ 경험 기계(experience machine)</strong></p><ul><li>완벽하게 행복한 삶을 <strong>영구히 경험하게 해 주는 기계</strong>(실제로는 기계에 연결된 상태)에 들어가겠는가? <strong>많은 사람이 거부</strong>한다 — <em>우정의 경험</em>만이 아니라 <strong>실제 우정</strong>, <em>성취감</em>만이 아니라 <strong>실제 성취</strong>를 원한다. 삶의 가치가 <strong>즐거운 경험 이상</strong>의 것을 포함함을 시사한다.</li></ul><p><strong>⑦ 과도한 요구</strong></p><ul><li>돈을 사소한 사치에 쓸까, <strong>심각한 고통을 막는 기부</strong>에 쓸까? 기부가 훨씬 큰 효용을 낳는다면 <strong>도덕적으로 기부해야 하나?</strong> 그렇다면 공리주의는 <strong>우리 자원이 다른 곳에서 더 큰 복지를 낳을 때마다 대부분의 개인적 프로젝트를 희생</strong>하라고 요구할 수 있고, <strong>의무와 칭찬할 만하지만 선택적인 행동의 경계</strong>를 유지하기 어려워진다.</li></ul><p><strong>⑧ 예측의 어려움</strong></p><ul><li>결과는 <strong>예측하기 어렵고</strong>, 정책은 <strong>의도하지 않은 효과</strong>를 낳으며, 단기 이익이 장기 해악을 낳을 수 있다. 일곱 차원은 <strong>불확실성을 인식하게는 하지만 없애지는 못한다.</strong> 낙관적 기관은 이익을 자신 있게 예측하면서 <strong>위험을 취약한 인구에게 전가</strong>할 수 있다 → <strong>책임 있는 계산</strong>은 불확실성, 오류, <strong>기관의 자기 이익</strong> 가능성을 포함해야 한다.</li></ul><p><strong>⑨ 적응적 선호(adaptive preferences)</strong></p><ul><li>안전한 작업 환경을 경험해 본 적 없는 노동자는 <strong>만족했다고 답할 수</strong> 있고, 여성이 불평등한 돌봄 노동 분배를 <strong>정상화된 불평등이라 받아들일</strong> 수 있으며, 소외 집단은 <strong>저항이 위험하니 기대를 낮춰 말할</strong> 수 있다. 공리주의가 <strong>보고된 만족</strong>만 측정하면 <strong>부정의를 재생산</strong>할 수 있다 → <strong>진짜 웰빙과 억압에 대한 적응을 구별</strong>해야 한다.</li></ul><p><strong>⑩ 전문가 행정과 시민의 자율</strong></p><ul><li>벤담의 기풍은 전문가가 정보를 모으고 인구를 분류하고 행동을 관리하도록 <strong>초대</strong>한다 — <strong>인간 개혁</strong>을 도울 수 있지만, 정부가 &quot;모델이 최대의 선을 계산했다&quot;고 주장하며 <strong>시민을 정치적 행위자가 아니라 데이터 포인트</strong>로 취급할 수 있다. 시민이 <strong>선택한 적 없는 기준</strong>으로 알고리즘이 복지를 최적화할 수도 있다. 그래서 <strong>자율성과 민주적 참여</strong>가 중요한 <strong>교정 수단</strong>으로 남는다.</li></ul><p><strong>⑪ 벤담을 단순화하지 말 것</strong></p><ul><li>벤담은 흔히 <strong>행위 공리주의자</strong>(행위의 경향을 평가)로 소개되지만, 법·정치철학에서는 <strong>제도, 규칙, 기대, 간접 효과</strong>에 깊이 관심을 둔다. <strong>안정된 규칙</strong>(예: 속이지 않기)이 <strong>경우마다 거짓말을 허용하는 것보다 더 큰 효용</strong>을 낼 수 있고, <strong>기대를 보호하는 법체계</strong>는 광범위한 불안을 막는다. → &quot;모든 고립된 행위를 처음부터 계산하라&quot;로 <strong>조악하게 축소하지 말 것</strong>. 그의 이론은 <strong>제도적으로 더 복잡</strong>하다.</li></ul><h2 id="_9-현대-사례-적용-슬라이드-16쪽-—-일부만-진행" tabindex="-1">9. 현대 사례 적용 (슬라이드 16쪽 — 일부만 진행) <a class="header-anchor" href="#_9-현대-사례-적용-슬라이드-16쪽-—-일부만-진행" aria-label="Permalink to &quot;9. 현대 사례 적용 (슬라이드 16쪽 — 일부만 진행)&quot;">​</a></h2><ul><li><strong>소셜 미디어 플랫폼</strong>: 알고리즘이 <strong>참여도(engagement)</strong> 를 극대화한다. 참여는 클릭·시청 시간·반응·공유·재방문으로 <strong>쉽게 측정</strong>되지만 <strong>참여 ≠ 효용</strong>. 벤담의 차원으로 보면: <ul><li>강도: 보통 / 확실성·근접성: <strong>높음, 즉각적</strong></li><li>다산성: 높음(상호작용이 다음 상호작용을 부름)</li><li><strong>순수성: 불안·불면·양극화·의존을 낳으면 낮음</strong></li><li><strong>범위: 수십억 명이 영향받아 막대함</strong></li><li>교훈: <strong>쉽게 측정되는 대리 지표를 진짜 행복과 혼동하지 말라.</strong></li></ul></li><li><strong>복지 AI</strong>: 복지 신청자 중 누가 부정을 저지를지 예측하는 AI는 <strong>행정 비용을 줄일 수</strong> 있지만 <strong>오탐(거짓 고발)</strong> 은 <strong>소득 상실·굴욕·불안</strong>을 낳는다. (시간이 끝나 여기서 마무리)</li></ul><hr><h2 id="정리-한-문장" tabindex="-1">정리 한 문장 <a class="header-anchor" href="#정리-한-문장" aria-label="Permalink to &quot;정리 한 문장&quot;">​</a></h2><blockquote><p>벤담은 <strong>쾌락과 고통을 여섯 개(후에 일곱 개) 차원에서 비교</strong>해 정책을 평가하게 하고, 그 평가는 <strong>개인 → 합산</strong>의 순서로 진행한다. 이 방법은 <strong>고통을 가시화하고 특권에 도전</strong>하지만, <strong>측정의 편향, 권리, 분배, 소수자, 질적 차이, 적응적 선호, 기술·행정의 지배</strong>라는 반론에 늘 서 있다.</p></blockquote><p><em>출처: 2026-10-12 윤리학 001분반 6주차-3 TransLive 자막(윤지영 교수)을 바탕으로 직접 재구성. 자막 전문은 <a href="./Raw-Transcripts/2026-10-12_week6-3.html">Raw-Transcripts</a>에 보관. 자막 오류(인물명·용어)는 맥락에 맞게 바로잡았고, 슬라이드 쪽수는 수업 순서와 <code>26-2 윤리학 6강.pdf</code> 제목을 대조해 추정했다.</em></p>',53)])])}const c=o(g,[["render",l]]);export{q as __pageData,c as default};
